with open('26-festival.txt') as f:
    n = int(f.readline())
    by_room = {}
    for line in f:
        room, start, finish = map(int, line.split())
        by_room.setdefault(room, []).append((start, finish))

best_room = best_count = 0
for room in sorted(by_room):
    end = count = 0
    for start, finish in sorted(by_room[room], key=lambda row: row[1]):
        if start >= end:
            count += 1
            end = finish
    if count > best_count:
        best_count = count
        best_room = room
print(best_count, best_room)
